  localId: LocalId;
  rid?: string;
  createdAt: Date;
  modifiedAt?: Date;
  authorId: LocalId;
};

export type CrossAppSchemaBase = CrossAppBase & {
  metadata?: Json;
};

// A node schema
export type CrossAppNodeSchema = CrossAppSchemaBase & {
  label: string;
  template?: string;
  templateTitle?: string;
  format?: string;
  slotDefinitions?: Record<string, LocalId | undefined>;
};
};

// A node instance
export type CrossAppNode = CrossAppBase & {
  nodeType: LocalId;
