import json
import os
import sys
import urllib.request

MILESTONE_ID = "ef992227-fafc-4687-ae46-ac9080dba637"
EXCLUDE = {"ENG-2416"}
OUT = sys.argv[1]

QUERY = """
query($id: String!) {
  projectMilestone(id: $id) {
    name
    description
    project { name description url }
    issues(first: 100, filter: { state: { type: { nin: ["completed", "canceled"] } } }) {
      nodes {
        identifier title url
        state { name }
        parent { identifier }
        description
        relations { nodes { type relatedIssue { identifier } } }
        inverseRelations { nodes { type issue { identifier } } }
        comments(first: 100) { nodes { body createdAt user { name } parent { id } } }
      }
    }
  }
}
"""

req = urllib.request.Request(
    "https://api.linear.app/graphql",
    data=json.dumps({"query": QUERY, "variables": {"id": MILESTONE_ID}}).encode(),
    headers={"Authorization": os.environ["LINEAR_API_KEY"], "Content-Type": "application/json"},
)
data = json.load(urllib.request.urlopen(req))
if "errors" in data:
    sys.exit(json.dumps(data["errors"], indent=2))

m = data["data"]["projectMilestone"]
issues = [i for i in m["issues"]["nodes"] if i["identifier"] not in EXCLUDE]
by_id = {i["identifier"]: i for i in issues}


def depth(i):
    d, p = 0, i["parent"]
    while p and p["identifier"] in by_id:
        d, p = d + 1, by_id[p["identifier"]]["parent"]
    return d


def root(i):
    while i["parent"] and i["parent"]["identifier"] in by_id:
        i = by_id[i["parent"]["identifier"]]
    return i["identifier"]


def tree_order():
    out = []

    def visit(ident):
        out.append(by_id[ident])
        kids = sorted(k["identifier"] for k in issues if k["parent"] and k["parent"]["identifier"] == ident)
        for k in kids:
            visit(k)

    for r in sorted({root(i) for i in issues}):
        visit(r)
    return out


lines = [
    f"# Context: {m['project']['name']}, milestone \"{m['name']}\"",
    "",
    "Input for the first OpenSpec call (ENG-2416). Every open ticket in the milestone, with its description and comments, exported from Linear.",
    "",
    "## Project",
    "",
    m["project"]["description"] or "",
    "",
    "## Milestone",
    "",
    m["description"] or "",
    "",
    "## Ticket tree",
    "",
]
ordered = tree_order()
for i in ordered:
    lines.append(f"{'  ' * depth(i)}- {i['identifier']} {i['title']} ({i['state']['name']})")
lines.append("")

for i in ordered:
    rels = [f"{r['type']} {r['relatedIssue']['identifier']}" for r in i["relations"]["nodes"]]
    rels += [f"{r['type']} by {r['issue']['identifier']}" for r in i["inverseRelations"]["nodes"]]
    lines += [
        "---",
        "",
        f"## {i['identifier']} {i['title']}",
        "",
        f"- Link: {i['url']}",
        f"- Status: {i['state']['name']}",
        f"- Parent: {i['parent']['identifier'] if i['parent'] else 'none'}",
        f"- Links: {', '.join(sorted(rels)) or 'none'}",
        "",
        (i["description"] or "(no description)").strip(),
        "",
    ]
    comments = sorted(i["comments"]["nodes"], key=lambda c: c["createdAt"])
    if comments:
        lines += ["### Comments", ""]
        for c in comments:
            who = (c["user"] or {}).get("name", "unknown")
            reply = " (reply)" if c["parent"] else ""
            lines.append(f"- {c['createdAt'][:10]}, {who}{reply}: " + c["body"].strip().replace("\n", "\n  "))
        lines.append("")

with open(OUT, "w") as f:
    f.write("\n".join(lines))
print(f"{len(ordered)} tickets, {sum(len(l) for l in lines)} chars -> {OUT}")
print("\n".join(l for l in lines if l.startswith(("- ENG", "- FEE", "  - ", "    - "))))
